 1→//! Step resolution and execution.
 2→//!
 3→//! This module provides the core step execution engine for Bivvy:
 4→//!
 5→//! - [`ResolvedStep`] - A fully resolved step ready for execution
 6→//! - [`execute_step`] - Execute a step with environment and hooks
 7→//! - [`run_check`] - Run completed checks for idempotency
 8→//! - [`StepStatus`] - Track step execution state
 9→//! - [`StepResult`] - Capture execution results
10→//!
11→//! # Example
12→//!
13→//! ```no_run
14→//! use bivvy::steps::{ResolvedStep, execute_step, ExecutionOptions, StepStatus};
15→//! use bivvy::config::InterpolationContext;
16→//! use std::collections::HashMap;
17→//! use std::path::Path;
18→//!
19→//! // Create a resolved step
20→//! let step = ResolvedStep::from_config("install", &Default::default(), None);
21→//!
22→//! // Execute with options
23→//! let options = ExecutionOptions {
24→//!     force: false,
25→//!     dry_run: true,
26→//!     capture_output: true,
27→//!     ..Default::default()
28→//! };
29→//!
30→//! let ctx = InterpolationContext::new();
31→//! let result = execute_step(
32→//!     &step,
33→//!     Path::new("."),
34→//!     &ctx,
35→//!     &HashMap::new(),
36→//!     &options,
37→//!     None,
38→//! ).unwrap();
39→//!
40→//! match result.status() {
41→//!     StepStatus::Completed => println!("Step completed successfully"),
42→//!     StepStatus::Skipped => println!("Step was already complete"),
43→//!     StepStatus::Failed => println!("Step failed: {}", result.error.unwrap_or_default()),
44→//!     _ => {}
45→//! }
46→//! ```
